import { APISchemaBase, type Attribute, type Prim, type Stage } from 'typescript-usd/usd'

/**
 * UsdGeomPrimvarsAPI encodes geometric "primitive variables",
 * as UsdGeomPrimvar, which interpolate across a primitive's topology,
 * can override shader inputs, and inherit down namespace.
 *
 * \section usdGeom_PrimvarFetchingAPI Which Method to Use to Retrieve Primvars
 *
 * While creating primvars is unambiguous (CreatePrimvar()), there are quite
 * a few methods available for retrieving primvars, making it potentially
 * confusing knowing which one to use.  Here are some guidelines:
 *
 * \li If you are populating a GUI with the primvars already available for 
 * authoring values on a prim, use GetPrimvars().
 * \li If you want all of the "useful" (e.g. to a renderer) primvars
 * available at a prim, including those inherited from ancestor prims, use
 * FindPrimvarsWithInheritance().  Note that doing so individually for many
 * prims will be inefficient.
 * \li To find a particular primvar defined directly on a prim, which may
 * or may not provide a value, use GetPrimvar().
 * \li To find a particular primvar defined on a prim or inherited from
 * ancestors, which may or may not provide a value, use 
 * FindPrimvarWithInheritance().
 * \li To *efficiently* query for primvars using the overloads of
 * FindPrimvarWithInheritance() and FindPrimvarsWithInheritance(), one
 * must first cache the results of FindIncrementallyInheritablePrimvars() for
 * each non-leaf prim on the stage. 
 */
export class PrimvarsAPI extends APISchemaBase {
  static readonly typeName: string = "PrimvarsAPI"

  static get(stage: Stage, path: string): PrimvarsAPI {
    return new PrimvarsAPI(stage.getPrim(path), stage)
  }

  static getSchemaAttributeNames(includeInherited = true): string[] {
    const names = includeInherited
      ? []
      : []
    return names
  }

  // --(BEGIN CUSTOM CODE)--

  // Creates primvars:NAME with the given value type, interpolation and
  // element size; elementSize is authored only when positive
  // (UsdGeomPrimvarsAPI::CreatePrimvar, primvarsAPI.cpp:97-115).
  createPrimvar(
    name: string, typeName: string, interpolation?: Interpolation, elementSize = -1,
  ): Attribute {
    const attr = this._declareAttr(`${PREFIX}${name}`, typeName)
    if (interpolation) attr.setMetadata('interpolation', interpolation)
    if (elementSize > 0) attr.setMetadata('elementSize', elementSize)
    return attr
  }

  setIndices(name: string, indices: number[]): void {
    this._declareAttr(`${PREFIX}${name}:indices`, 'int[]').set(indices)
  }

  // ---- Reading ----

  // Enumerates all primvars on the prim (skipping :indices/:interpolation
  // sibling attributes).
  static getPrimvars(prim: Prim): Primvar[] {
    const names = new Set<string>()
    for (const attrName of prim.attrNames) {
      if (!attrName.startsWith(PREFIX)) continue
      if (attrName.endsWith(':indices') || attrName.endsWith(':interpolation')) continue
      names.add(attrName.slice(PREFIX.length))
    }
    return [...names].sort().map(n => new Primvar(prim, n))
  }

  static getPrimvar(prim: Prim, name: string): Primvar | null {
    const pv = new Primvar(prim, name)
    // primvarsAPI.cpp:177-182 constructs from the attribute, not its default
    // value. Time-sampled-only attributes remain valid inheritable primvars.
    const type = prim.getAttr(pv.attrName)?.typeName
    return type && type !== 'rel' ? pv : null
  }

  static hasPrimvar(prim: Prim, name: string): boolean {
    return PrimvarsAPI.getPrimvar(prim, name) !== null
  }

  findPrimvarWithInheritance(name: string): Primvar | null {
    const local = PrimvarsAPI.getPrimvar(this._prim, name)
    if (local?.hasAuthoredValue()) return local
    let path = parentPath(this._prim.path)
    while (path && path !== '/') {
      const prim = this._stage.getPrim(path)
      const inherited = prim ? PrimvarsAPI.getPrimvar(prim, name) : null
      if (inherited?.hasAuthoredValue()) {
        return inherited.getInterpolation() === 'constant' ? inherited : null
      }
      path = parentPath(path)
    }
    return null
  }

  findPrimvarsWithInheritance(): Primvar[] {
    const paths: string[] = []
    let path: string | null = this._prim.path
    while (path && path !== '/') {
      paths.unshift(path)
      path = parentPath(path)
    }
    const inherited = new Map<string, Primvar>()
    for (const primPath of paths) {
      const prim = this._stage.getPrim(primPath)
      if (!prim) continue
      for (const primvar of PrimvarsAPI.getPrimvars(prim)) {
        if (!primvar.hasAuthoredValue()) continue
        if (primPath === this._prim.path || primvar.getInterpolation() === 'constant') {
          inherited.set(primvar.name, primvar)
        } else {
          inherited.delete(primvar.name)
        }
      }
    }
    return [...inherited.values()].sort((a, b) => a.name.localeCompare(b.name))
  }

  hasPossiblyInheritedPrimvar(name: string): boolean {
    return this.findPrimvarWithInheritance(name) !== null
  }
}

// UsdGeomPrimvarsAPI / UsdGeomPrimvar — generic primvar access.
// A primvar is an attribute in the `primvars:` namespace with an
// interpolation token and optional index array. In this implementation the
// interpolation and indices live in sibling attributes:
//   primvars:NAME                 — the value
//   primvars:NAME:interpolation   — interpolation token
//   primvars:NAME:indices         — optional int[] indices
// Reference: pxr/usd/usdGeom/primvarsAPI.h, primvar.h


import { SchemaBase } from 'typescript-usd/usd'
import type { Interpolation } from './mesh.ts'
import { attrVal, asToken, toInt32 } from './valueUtils.ts'

const PREFIX = 'primvars:'

export class Primvar {
  constructor(
    private readonly _prim: Prim,
    // Primvar name WITHOUT the 'primvars:' prefix (e.g. 'st', 'displayColor')
    readonly name: string,
  ) {}

  get attrName(): string { return `${PREFIX}${this.name}` }
  get primPath(): string { return this._prim.path }

  hasValue(): boolean {
    return this._prim.getAttr(this.attrName)?.hasValue() ?? false
  }

  hasAuthoredValue(): boolean {
    return this._prim.getAttr(this.attrName)?.hasAuthoredValue() ?? false
  }

  getValue(time?: number): unknown {
    return attrVal(this._prim, this.attrName, time)
  }

  getInterpolation(): Interpolation {
    // Real USD stores primvar interpolation as attribute metadata (the
    // `interpolation` field); prefer it, falling back to the sibling-attr
    // convention some assets use, then the UsdGeom default.
    const meta = this._prim.getAttr(this.attrName)?.getField('interpolation')
    if (typeof meta === 'string') return meta as Interpolation
    return asToken(attrVal(this._prim, `${this.attrName}:interpolation`), 'constant') as Interpolation
  }

  getIndices(time?: number): Int32Array | null {
    const v = toInt32(attrVal(this._prim, `${this.attrName}:indices`, time))
    return v && v.length > 0 ? v : null
  }

  isIndexed(): boolean {
    return this.getIndices() !== null
  }
}


function parentPath(path: string): string | null {
  if (path === '/' || !path.startsWith('/')) return null
  const split = path.lastIndexOf('/')
  return split === 0 ? '/' : path.slice(0, split)
}
